// ---- Avatar picker ----
// Settings, Avatar: 44 dp circles, one per avatar. Each is a picture that moves in the bubble.
// Pager is the manifest's default launcher and the pick until the user changes it.
const avImg = src => `<img src="${src}" alt="" width="44" height="44" style="display:block;width:44px;height:44px;max-width:none">`;
const AVATARS = [
  ["Pager", "var(--m-brand)", avImg("data:image/png;base64,")],
  ["Clay", "#0A0E0C", avImg("data:image/png;base64,")],
  ["Jelly", "#0A0E0C", avImg("data:image/png;base64,")],
];
function avatarPicker() {
  const pick = S.avatar || "Pager";
  const opt = (key, [, ground, art]) => { const on = pick === key; return `<button data-set="avatar:${key}" aria-pressed="${on}" style="flex:none;border:0;background:transparent;padding:0;display:grid;justify-items:center;gap:4px;font-size:11px;color:var(${on ? "--m-ink" : "--m-muted"});font-weight:${on ? 600 : 400}">
    <span style="width:44px;height:44px;border-radius:50%;overflow:hidden;background:${ground};display:grid;place-items:center;${on ? "outline:2px solid var(--m-ink);outline-offset:-2px" : ""}">${art}</span>${key}</button>`; };
  return `<div class="label" style="padding:4px">Avatar</div>
      <div style="display:flex;gap:10px;overflow-x:auto;scrollbar-width:none;margin:4px -16px 0;padding:2px 20px 4px">${AVATARS.map(a => opt(a[0], a)).join("")}</div>
      <div class="muted" style="font-size:11px;line-height:16px;padding:2px 4px 0">How Beep looks on your home screen and in the bubble. The home screen may take a moment to update.</div>`;
}
